def unit_of_work(metadata=None, timeout=None):
    """Decorator for transaction functions that allows extra control over how the transaction is carried out."""
    def inner_unit_of_work(function):
        def wrapper(*args, **kwargs):
            tx = args[0]
            if metadata:
                tx.set_metadata(metadata)
            if timeout:
                tx.set_timeout(timeout)
            return function(*args, **kwargs)
        return wrapper
    return inner_unit_of_work

