def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    """
    def decorator(func):
        lru_cache = []
        ttm = {}

        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(kwargs.items()))
            try:
                expiration = ttm[key]
            except KeyError:
                if len(lru_cache) >= maxsize:
                    lru_cache.pop(0)
                lru_cache.append(key)
                ttm[key] = timer() + ttl
            else:
                if expiration <= timer():
                    lru_cache.append(key)
                    ttm[key] = timer() + ttl
            try:
                return func(*args, **kwargs)
            finally:
                try:
                    lru_cache.remove(key)
                except ValueError:
                    pass

        wrapper.cache = ttm.keys()
        wrapper.ttl = ttl
        wrapper.maxsize = maxsize
        wrapper.lru_cache = lru_cache
        wrapper.timer = timer
        wrapper.typed = typed

        return wrapper

    return decorator
