def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        from functools import wraps
        from typing import Optional

        cache: dict = {}
        hits = misses = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args + (frozenset(kwargs.items()) if typed else tuple(kwargs.items()))
            now = timer()
            try:
                value, expiration = cache[key]
                if now > expiration:
                    raise KeyError
            except KeyError:
                misses += 1
                value = func(*args, **kwargs)
                cache[key] = (value, now + ttl)
                if len(cache) > maxsize:
                    cache.popitem(last=False)
            else:
                hits += 1
            return value

        def clear():
            cache.clear()
            hits = misses = 0

        wrapper.hits = property(lambda: hits)
        wrapper.misses = property(lambda: misses)
        wrapper.maxsize = property(lambda: maxsize)
        wrapper.ttl = property(lambda: ttl)
        wrapper.clear = clear
        return wrapper
    return decorator
