def lru_cache(maxsize=128, typed=False):
    if typed:
        d = {'called': []}
        d['miss'] = lambda key: len(d['called'])
        d['hit'] = lambda key: d['called'].index(key)
        d['bystand'] = []

        def lru_wrapper(fn):
            @functools.wraps(fn)
            def wrapper(*args, **kwargs):
                key = hash(str(args) + str(kwargs))
                if (d['miss'](key) < maxsize):
                    d['called'].append(key)
                    v = fn(*args, **kwargs)
                    d['bystand'].append(v)
                    return v
                else:
                    d['called'].append(key)
                    d['bystand'].remove(d['hit'](key))
                    v = fn(*args, **kwargs)
                    d['bystand'].append(v)
                    return v
            return wrapper
        return lru_wrapper
    else:
        d = {}
        d['called'] = OrderedDict()
        d['miss'] = lambda key: len(d['called'])
        d['hit'] = lambda key: list(d['called'].keys()).index(key)

        def lru_wrapper(fn):
            @functools.wraps(fn)
            def wrapper(*args, **kwargs):
                key = hash(str(args) + str(kwargs))
                if (d['miss'](key) < maxsize):
                    d['called'][key] = fn(*args, **kwargs)
                    return d['called'][key]
                else:
                    k = list(d['called'].keys())[0]
                    d['called'].pop(k)
                    d['called'][key] = fn(*args, **kwargs)
                    return d['called'][key]
            return wrapper
        return lru_wrapper
