def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        access_count = {}
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                v = cache[args, kwargs]
                access_count[k] += 1
            except KeyError:
                pass  # key not found
            v = func(*args, **kwargs)
            if len(cache) < maxsize:
                cache[k] = v
                access_count[k] = 1
            else:
                # evict the LFU entry
                lfu_items = sorted(access_count.items(), key=lambda x: x[1])
                del cache[lfu_items[0]]
                del access_count[lfu_items[0]]
            return v
        return _update_wrapper(wrapper, func)
    return decorator
