def normalize_values(parameter_values, parameters):
    """Normalize passed argument values to the type specified in the parameter list

    :param parameter_values: List of values to be normalized
    :type  parameter_values: list

    :param parameters: Parameter list to be used for normalization
    :type  parameters: list

    :rtype: list

    :raises: ValueError(Missing parameters in parameter list)

    :raises: ValueError(Missing parameter values)

    :raises: TypeError(Parameter type mismatch)

    :raises: TypeError(Value type mismatch)
    """
    normalized_values = []
    for param_value, param in zip(parameter_values, parameters):
        if "name" not in param:
            continue
        param_name = param["name"]
        value = param_value.get("value")
        if value is None:
            raise ValueError("Missing parameter values")
        param_type = param["type"]
        value_type = type(value)
        if param_type in ("string", "number", "integer", "boolean", "enum"):
            value_ permitted = param.get("permitted", [])
            if value_type is not param_type and value_type not in permitted:
                raise TypeError("Value type mismatch")
            normalized_value = value
        elif param_type is "text":
            if value_type is not str:
                raise TypeError("Value type mismatch")
            normalized_value = value
        elif param_type is "choice":
            if value_type is not Choice:
                raise TypeError("Value type mismatch")
            if value not in param.get("options", []):
                raise ValueError("Unknown value for choice parameter")
            normalized_value = value
        elif param_type is "group":
            normalized_value = normalize_values(value, param["parameters"])
        else:
            raise ValueError("Unsupported parameter type")
        param_size = param.get("size")
        if param_size:
            param_length, param_minLength, param_maxLength = param_size
            value_length = len(value)
            if value_length is not param_length and value_length is not param_maxLength:
                raise ValueError("Invalid length of parameter values")
            if param_minLength and value_length is not param_minLength:
                raise ValueError("Insufficient number of parameter values")
        normalized_values.append(normalized_value)
    return normalized_values

