def fms(x, mu, sigma):
    """Compute the FMS function between x and [mu-sigma, mu, mu+sigma]

    Parameters
    ----------
    x : float
        Value of the function.
    mu : float
    sigma : float
        Parameters of the function.

    Returns
    -------
    float
        Returns the value of the FMS function.
    """
    if x < mu - sigma:
        return 1
    elif x < mu:
        return (x - (mu - sigma))**2 / ((mu - 2 * sigma)**2)
    elif x < mu + sigma:
        return (mu + sigma - x)**2 / ((mu + sigma - 2 * sigma)**2)
    else:
        return 0

def fms_transform(kernel_function,
                  fms_values,
                  transform_values,
                  width=200,
                  min_value=0.,
                  max_value=255.,
                  fmspoints=20,
                  outputfile='values.txt'):
    """Apply the FMS transformation to a kernel function.

    Parameters
    ----------
    kernel_function : function
        Kernel function to be used.
    fms_values : tuple
        Tuple with the values of the endpoints of the FMS function
        (mu, sigma).
    transform_values : tuple
        Tuple with the values of the transform points (t1, t2, ..., tn).
    width : int, optional
        Width of the kernel function, by default 200.
    min_value : float, optional
        Minimum value of the output, by default 0.
    max_value : float, optional
        Maximum value of the output, by default 255.
    fmspoints : int, optional
        Number of points to be calculated in the FMS range, by default 20.
    outputfile : str, optional
        Name of the generated file where the output will be stored,
        by default "values.txt".

    Raises
    ------
    ValueError
        If the parameters are not in the specified range.

    Returns
    -------
    np.array
        Array containing the output values of the FMS transformation.
    """
    # checking the parameters and raising ValueError when needed
    if not (0 <= min_value <= max_value):
        raise ValueError(
            "`min_value` should be between 0 and `max_value`")
    elif not len(transform_values) == 3:
        raise ValueError("`transform_values` should be a tuple with 3 values")
    elif not (0 < width <= 200):
        raise ValueError("`width` should be between 1 and 200")
    else:
        # calculating the fms points
        x = np.linspace(min(fms_values), max(fms_values), fmspoints)
        # iterating over the elements of the transform_values
        output = []
        for value in transform_values:
            # calculating the kernel function at each point
            kernel_function = kernel_function(x, value, width)
            # adding the kernel values to the output list
            output.append(kernel_function)
        # finalizing output as a numpy array
        output = np.array(output)
        # normalizing output values
        output = norm(output)
        #returning the normalized values
        return output

