    """Compare two strings and returns their equivalent.

    :param text1: First sequence to be compared.
    :param text2: Second sequence to be compared.
    :return: A Filler that can be used to fill the equivalent of both strings.
    """
    if len(text1) == len(text2):
        return EqualFiller(text1)

    seq_match = SequenceMatcher(None, text1, text2)
    opcodes = list(seq_match.get_opcodes())

    if len(opcodes) == 1:
        if opcodes[0][0] == "replace":
            return ReplaceFiller(text1, text2)
        elif opcodes[0][0] == "insert":
            return InsertFiller(text1, text2)
        elif opcodes[0][0] == "delete":
            return DeleteFiller(text1, text2)

    if len(opcodes) == 2 and opcodes[0][0] == "delete" and opcodes[1][0] == "insert":
        return ReplaceFiller(text1, text2)

    return MultipleFiller(opcodes, text1, text2)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """

    if not seq or isinstance(seq, FillRequestSeq):
        return True

    if isinstance(seq, FillRequest):
        return True

    if not all(isinstance(x, FillRequest) for x in seq):
        return False

    return True

