def difference(d1, d2, level=-1):
      """Return a dictionary with items from *d1* not contained in *d2*.

      *level* sets the maximum depth of recursion. For infinite recursion,
      set that to -1. For level 1,
      if a key is present both in *d1* and *d2* but has different values,
      it is included into the difference.
      See :func:`intersection` for more details.

      *d1* and *d2* remain unchanged. However, *d1* or some of its
      subdictionaries may be returned directly.
      Make a deep copy of the result when appropriate.

      .. versionadded:: 0.5
         add keyword argument *level*.
      """
      # Base cases:
      # 1. d1 is empty or level is 0.
      if not d1 or level == 0:
          return dict(d1)
      # 2. d2 is empty.
      if not d2:
          return dict(d1)
      # Initialize the result.
      result = {}
      for k, v in d1.items():
          # k is not in d2 OR d2[k] != v.
          if k not in d2 or d2[k] != v:
              result[k] = v
      for k, v in d2.items():
          # k is not in d1.
          if k not in result:
              result[k] = v
      # Recursive cases: d1 and d2 are non-empty and level is not 0.
      if level < 0:
          for k, v in d1.items():
              if k in d2 and isinstance(v, dict):
                  result[k] = difference(v, d2[k], level)
              elif k in d2 and k not in result:
                  result[k] = v
          for k, v in d2.items():
              if k not in result:
                  result[k] = v
      return result

