        elif isinstance(value, unicode):
            try:
                re.match(LABEL_VALUE_REGEX, value)
            except re.error:
                messages.append({value: "Label value '%s' does not match the regex %s" % (value, LABEL_VALUE_REGEX)})
        else:
            messages.append({key: "Label key '%s' must be a string" % key})
            messages.append({value: "Label value '%s' must be a string" % value})
    if messages:
        raise ValidationError(messages)
