def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    # Create a new dictionary from manifest_dict and replace all non-list and non-dict values by None.
    observer_schema = {k: (manifest_dict[k] if isinstance(manifest_dict[k], (list, dict)) else None) for k in manifest_dict}

    # If first_level==True, copy the values of the identifying fields from the manifest file.
    if first_level:
        observer_schema["apiVersion"] = manifest_dict["apiVersion"]
        observer_schema["kind"] = manifest_dict["kind"]
        observer_schema["metadata"] = manifest_dict["metadata"]
        if manifest_dict.get("status"):
            observer_schema["status"] = manifest_dict["status"]

    return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    new_dict = {}
    for k, v in manifest_dict.items():
        if isinstance(v, dict):
            new_dict[k] = generate_default_observer_schema_dict(v, False)
        elif isinstance(v, (list, tuple)):
            new_dict[k] = [generate_default_observer_schema_dict(item, False) for item in v]
        else:
            new_dict[k] = None

    if first_level:
        for k, v in new_dict.items():
            if isinstance(v, (list, tuple)):
                for item in v:
                    if k in item:
                        item[k] = manifest_dict[k]
            else:
                new_dict[k] = manifest_dict[k]

    return new_dict

