def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    observed_fields = get_observed_fields(observer_schema)

    for i, field in enumerate(observed_fields):
        value = response[i]
        if not last_applied_manifest[i]:
            last_applied_manifest[i] = value
        else:
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[i], observer_schema[i], value
            )

    return last_applied_manifest

# Function to get observed fields from observer schema
def get_observed_fields(observer_schema):
    if isinstance(observer_schema, list):
        return [get_observed_fields(item) for item in observer_schema]
    return observer_schema["fields"]

# Function to update a partial last_applied_manifest from a partial response
def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    observed_fields = get_observed_fields(observer_schema)

    for field, value in response.items():
        if field not in observed_fields:
            continue
        if not last_applied_manifest[field]:
            last_applied_manifest[field] = value
        else:
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field],
                observer_schema["fields"][field],
                value,
            )

    return last_applied_manifest

