def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    # Traverse through the response and observer schema
    for resp_item, obs_item in zip(response, observer_schema):
        # If the item in the response is a list, recurse into it
        if isinstance(resp_item, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest, obs_item, resp_item)
        # If the item in the response is a dictionary, recurse into it
        elif isinstance(resp_item, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest, obs_item, resp_item)
        # If the item in the response is a primitive type, initialize its value in the last_applied_manifest
        else:
            if obs_item not in last_applied_manifest:
                last_applied_manifest[obs_item] = resp_item

    return last_applied_manifest
