def get_default_observer_schema(resource):
    """Create and return a default observer schema for the given Kubernetes resource.

    Args:
        resource (krake.data.kubernetes.Resource): The Kubernetes resource for which to create
            a default observer schema

    Returns:
        A default observer schema for the resource
    """
    observer_schema = {}
    for field in resource:
        if field == 'apiVersion' or field == 'kind':
            continue
        field_name = field.split('.')[-1]
        observer_schema[field_name] = {
            'resource': resource,
            'field': field,
        }
    return observer_schema

