def format(sql, params):
    # Convert in-style parameters to out-style parameters
    out_params = {}
    if isinstance(params, dict):
        # Named parameters
        for key, value in params.items():
            out_params[f"p_{key}"] = value
    else:
        # Ordinal parameters
        for i, value in enumerate(params, start=1):
            out_params[f"p_{i}"] = value

    # Sanitize SQL and replace in-style parameters with out-style parameters
    sanitized_sql = ""
    for part in sql.split("?"):
        if ":" in part:
            param_name = part.split(":")[1]
            if param_name in out_params:
                sanitized_sql += "?" + out_params[param_name]
            else:
                sanitized_sql += part
        else:
            sanitized_sql += part

    return sanitized_sql, out_params

def format(sql, params):
    if self.in_style == InStyle.named:
        assert isinstance(params, Mapping), "params must be a Mapping"
    elif self.in_style == InStyle.ordinal:
        assert isinstance(params, Sequence), "params must be a Sequence"
    else:
        raise ValueError(f"unknown in_style {self.in_style}")

    if self.out_style == OutStyle.named:
        formatted_params = {f"@{n}": v for n, v in params.items()}
    elif self.out_style == OutStyle.ordinal:
        formatted_params = {i: v for i, v in enumerate(params, start=1)}
    else:
        raise ValueError(f"unknown out_style {self.out_style}")

    formatted_sql = sql.format(**formatted_params)

    return formatted_sql, formatted_params

def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    sql (:class:`str` or :class:`bytes`) is the SQL query.

    many_params (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    # Check if sql is a string or bytes
    if isinstance(sql, str):
        sql = bytes(sql, self.encoding)

    # Check if many_params is a list, tuple, or set
    if isinstance(many_params, (list, tuple, set)):
        many_params = list(many_params)
    else:
        raise TypeError("many_params must be a list, tuple, or set")

    # Check if the params are a dict or a tuple
    if len(many_params) > 0:
        if isinstance(many_params[0], dict):
            pass
        elif isinstance(many_params[0], (list, tuple, set)):
            many_params = list(map(list, zip(*many_params)))
        else:
            raise ValueError("Params must be dict or tuple")
    else:
        raise ValueError("Params cannot be empty")

    # Create a list of out-style parameters
    out_params = []
    for params in many_params:
        out_params.append(self._params(params))

    # Replace in-style parameters with out-style parameters
    sql = sql.decode(self.encoding)
    for param in out_params:
        if isinstance(param, dict):
            for k, v in param.items():
                sql = sql.replace(':' + k, self.placeholder(v))
        else:
            for k, v in zip(param, out_params):
                sql = sql.replace(':' + k, self.placeholder(v))

    return sql, out_params

