def formatmany(self, sql, many_params):
    parameters = []
    for params in many_params:
        if isinstance(params, Mapping):
            for key, value in params.items():
                parameters.append(Parameter(key, value))
        elif isinstance(params, Sequence):
            for value in params:
                parameters.append(Parameter(value))
        else:
            raise TypeError("params must be a Mapping or Sequence")

    converted_params = []
    for param in parameters:
        if param.name is not None:
            converted_params.append({param.name: param.value})
        else:
            converted_params.append([param.value])

