def next_version(version: str):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    :param version: Existing version identifier.
    :return: Next version identifier.
    """
    major, minor, patch = version.split(".")
    if patch.isdigit():
        patch = int(patch)
        next_patch = str(patch + 1).zfill(len(patch))
    else:
        next_patch = "0"
    return ".".join([major, minor, next_patch])

def next_version(version: str) -> str:
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version == "":
        return "0.1.0"

    version_parts = version.split(".")
    release, major, minor = version_parts

    if release == "0" and major == "0" and minor == "0":
        return "1.0.0"

    if major == "0" and minor == "0":
        return f"{release}.1.0"

    if minor == "0":
        return f"{release}.{major}.1"

    return f"{release}.{major}.{minor + 1}"

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.directory, version_dir, INVENTORY_FILE)
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"{INVENTORY_FILE} not found in {version_dir}")
        # Check that the inventory is a valid JSON file
        with open(inventory_path, "r") as inventory_file:
            try:
                inventory = json.loads(inventory_file.read())
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON format in {INVENTORY_FILE}") from e
        # Check that the inventory is a mapping
        validate_is_mapping(INVENTORY_FILE, inventory)
        # Check that all the content digests are strings
        for content_digest in inventory.values():
            if not isinstance(content_digest, str):
                raise ValueError(f"{INVENTORY_FILE} contains non-string content digests")
    # Always save the root inventory
    self.save_root_inventory()
    # Check for differing content digests
    for version_dir in version_dirs[1:]:
        inventory_path = os.path.join(self.directory, version_dir, INVENTORY_FILE)
        with open(inventory_path, "r") as inventory_file:
            inventory = json.loads(inventory_file.read())
            if inventory != self.inventories[version_dir]:
                self.inventories[version_dir] = inventory
    # Handle the case where a previous version does not have a content digest for a file
    for version_dir in [vd for vd in version_dirs[1:] if vd not in self.inventories]:
        self.inventories[version_dir] = {}
    return self

