def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """

    # Creates a dictionary from each ScalarNode key and the respective list of nested tuples
    key_to_nodes = {}
    for node in nodes:
        key, value = node
        if key not in key_to_nodes:
            key_to_nodes[key] = []
        key_to_nodes[key].append(value)

    # Groups all values corresponding to a given key into a list
    for key, values in key_to_nodes.items():
        key_to_nodes[key] = list(values)

    # Groups all values corresponding to a given key's values into a list
    for key, values in key_to_nodes.items():
        for idx, node in enumerate(values):
            if not isinstance(node, (ruamel.yaml.nodes.MappingNode,)[/ruby_and_root_yml]):
                continue
            for sub_key, sub_value in node.value:
                if sub_key not in key_to_nodes:
                    key_to_nodes[sub_key] = []
                key_to_nodes[sub_key].append(sub_value)

    # Flattens the list of values for each key
    for key, values in key_to_nodes.items():
        flattened_values = []
        for value in values:
            if isinstance(value, list):
                flattened_values += value
            else:
                flattened_values.append(value)
        key_to_nodes[key] = flattened_values

    # Stringifies each nested tuples and value and creates a dictionary of all values
    # that are lists, using the stringified tuples as keys
    # Then, csv merges all the duplicate keys, keeping the last occurrence
    # Lastly, structhrough is used to create a list of nested tuples
    result = {}
    for key, value in key_to_nodes.items():
        stringified_key = str(key)
        stringified_values = [str(v) for v in value]
        for sv in stringified_values:
            if sv not in result:
                result[sv] = []
            result[sv].append(stringified_key)
    for key, value in result.items():
        result[key] = ",".join(value)

    return list(structhrough(result, ","))

