def deep_merge_nodes(nodes: List[Tuple[ruamel.yaml.nodes.ScalarNode, Union[ruamel.yaml.nodes.MappingNode, Any]]]) -> List[Tuple[ruamel.yaml.nodes.ScalarNode, Union[ruamel.yaml.nodes.MappingNode, Any]]]:
    def merge_nodes(node1: Any, node2: Any) -> Any:
        if isinstance(node1, ruamel.yaml.nodes.MappingNode) and isinstance(node2, ruamel.yaml.nodes.MappingNode):
            merged_node = ruamel.yaml.nodes.MappingNode()
            for key, val in chain(node1.value, node2.value):
                if key not in merged_node:
                    merged_node.value.append((key, val))
            return merged_node
        else:
            return node2

    merged_nodes = list()
    for key, node in nodes:
        idx = next((i for i, (k, _) in enumerate(merged_nodes) if k == key), None)
        if idx is not None:
            merged_nodes[idx] = (key, merge_nodes(node, merged_nodes[idx][1]))
        else:
            merged_nodes.append((key, node))

    return merged_nodes
