    merged_nodes = []
    for key, value_node in nodes:
        # Check if the key already exists in the merged nodes
        matched_node = next((matched_node for matched_node in merged_nodes if matched_node[0] == key), None)
        if matched_node:
            # If the value is a MappingNode, perform a deep merge
            if value_node.tag == 'tag:yaml.org,2002:map':
                merged_value = _deep_merge_mapping_nodes(matched_node[1], value_node)
                matched_node[1] = merged_value
            else:
                # If the value is not a MappingNode, the last one wins
                matched_node[1] = value_node
        else:
            merged_nodes.append((key, value_node))
    return merged_nodes

def _deep_merge_mapping_nodes(node_1, node_2):
    for key, value_node in node_2.items():
        if not key in node_1:
            node_1[key] = value_node
        elif key in node_1 and (key.tag == 'tag:yaml.org,2002:map' or key.tag == 'tag:yaml.org,2002:seq'):
            node_1[key] = _deep_merge_mapping_nodes(node_1[key], value_node)
