    def _merge_node_value(key, value, new_value):
        if isinstance(value, MappingNode):
            # Recursively merge the two mapping nodes
            for k, v in new_value.value:
                key, value = _merge_node_value(k, v, value)
            return key, value
        else:
            # The two nodes are non-MappingNode values, only the last one wins
            return key, new_value

    merged_nodes = []
    for node in nodes:
        # Check if the node is already in the merged list
        found = False
        for i, merged_node in enumerate(merged_nodes):
            if node[0] == merged_node[0]:
                # This node is already in the merged list, so merge its value with the existing node
                merged_nodes[i] = _merge_node_value(merged_node[0], merged_node[1], node[1])
                found = True
                break
        if not found:
            # This node is not in the merged list yet, so add it directly
            merged_nodes.append(node)

    return merged_nodes

def deep_merge_nodes(nodes):
    result = {}
    for node in nodes:
        if node.key.value not in result:
            result[node.key.value] = node.value
        else:
