def aggregate_values(node1, node2):
    if not isinstance(node1, ruamel.yaml.nodes.MappingNode):
        return node2
    result = {}
    for key, value in node1.value + node2.value:
        if key.value in result:
            result[key.value] = aggregate_values(value, result[key.value])
        else:
            result[key.value] = value
    return result






