def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        return 0

    size_number, size_unit = size.split(" ")
    size_number = float(size_number)
    size_unit = size_unit.upper()

    if size_unit == "B":
        return int(size_number * 1)
    elif size_unit == "KB":
        return int(size_number * 1000)
    elif size_unit == "MB":
        return int(size_number * 1000000)
    elif size_unit == "GB":
        return int(size_number * 1000000000)
    elif size_unit == "TB":
        return int(size_number * 1000000000000)
    elif size_unit == "PB":
        return int(size_number * 1000000000000000)
    elif size_unit == "EB":
        return int(size_number * 1000000000000000000)
    elif size_unit == "ZB":
        return int(size_number * 1000000000000000000000)
    elif size_unit == "YB":
        return int(size_number * 1000000000000000000000000)
    else:
        raise ValueError(f"Unsupported size unit: {size_unit}")

