            platforms = ['windows', 'cmd']
        elif sys.platform == 'linux':
            platforms = ['posix']
        else:
            # Unsupported platform
            raise ValueError(f'Unsupported platform: {sys.platform}')
    elif platform == 1:
        platforms = ['posix']
    elif platform == 0:
        platforms = ['windows', 'cmd']
    else:
        # Unsupported value for platform
        raise ValueError(f'Unsupported value for platform: {platform}')

    for platform in platforms:
        if platform == 'posix':
            pattern = r'\s+'
        elif platform == 'windows':
            pattern = r'^"((?:""|[^"])*)"$'
        elif platform == 'cmd':
            pattern = r'^"((?:""|[^"])*)"$'
        else:
            # Unsupported platform
            raise ValueError(f'Unsupported platform: {platform}')

        tokens = re.split(pattern, s)

