def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not inspect.isfunction(func):
        raise TypeError("func must be a function")
    if not isinstance(timeout, int):
        raise TypeError("timeout must be an integer")
    if extra_env is not None and not isinstance(extra_env, dict):
        raise TypeError("extra_env must be a dictionary")

    if extra_env is not None:
        env = dict(**os.environ, **extra_env)
    else:
        env = os.environ

    subproc = subprocess.Popen([sys.executable, "-c", func.__module__ + "." + func.__name__, *args],
                               stdout=subprocess.PIPE, env=env)
    output, err = subproc.communicate(timeout=timeout)
    if err:
        raise subprocess.CalledProcessError(subproc.returncode, func.__name__, output=bytes(err))
    return output.decode("utf-8")
