def load_config(config_file, overrides=None, resolve_env=True):
    """
    Load a configuration file (e.g., JSON or YAML) and return the parsed configuration.

    Args:
        config_file (str): Path to configuration file.
        overrides (dict, optional): Overrides for the configuration file. Defaults to None.
        resolve_env (bool, optional): Enable resolution of environment variables in the configuration. Defaults to True.

    Returns:
        dict: Parsed configuration.
    """
    if resolve_env:
