        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        if len(protocol_version) != 2:
            raise TypeError("protocol_version must be a 2-tuple")
        if protocol_version not in cls.AVAILABLE_FOR:
            return {}
        protocol_handlers[protocol_version] = cls.VERSIONED_HANDLER_CLASSES[protocol_version]
    else:
        protocol_handlers = cls.VERSIONED_HANDLER_CLASSES.copy()
    return protocol_handlers
