def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Check if sequence is already a sequence
    if isinstance(seq, (list, tuple, set)):
        return seq, type(seq)

    # Check if sequence is a string
    if isinstance(seq, (six.string_types, six.binary_type)):
        return _string_to_sequence(seq, bufsize), six.text_type

    # Default to sequence type for other inputs
    return seq, sequence

def _string_to_sequence(seq, bufsize=None):
    """Convert a string into a sequence.
    If *bufsize* is not None, the string is split into a
    sequence of chunks of *bufsize* length using the "in-place
    split" algorithm.
    """
    if bufsize is None:
        return list(seq)
    else:
        return [seq[i:i+bufsize] for i in range(0, len(seq), bufsize)]

