def _verify(iface, candidate, tentative=False, vtype=None):
    # Make sure the candidate claims that it provides the interface using iface.providedBy
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Candidate '{}' does not claim to provide interface '{}'".format(candidate, iface))

    # Make sure the candidate defines all the necessary methods
    for name, spec in iface.getRawMethods():
        try:
            candidate[name]
        except KeyError:
            raise zope.interface.Invalid("Candidate '{}' does not define method '{}'".format(candidate, name))

    # Make sure the methods have the correct signature
    for name, spec in iface.getRawMethods():
        # Retrieve the necessary method signature from the interface
        iface_sig = iface.__dict__["_Method__v_decl"].inverse[name][0][1][-1]
        # Retrieve the actual method signature from the candidate
        candidate_sig = candidate.__dict__[name].__code__.co_varnames[:iface_sig.args]
        if iface_sig.args != candidate_sig:
            raise zope.interface.Invalid("Method '{}' has incompatible signature".format(name))

    # Make sure the candidate defines all the necessary attributes
    for name in iface.names(iface.TYPE_ATTRIBUTE):
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define attribute '{}'".format(name))
    return True
