    # Starting with the explicit metaclass, if given, check if it is a valid metaclass
    if explicit_mc:
        try:
            if issubclass(explicit_mc, type):
                return explicit_mc
        except TypeError:
            pass

    # If no explicit metaclass was given, check bases for a __metaclass__ attribute
    for base in bases:
        if hasattr(base, '__metaclass__') and issubclass(base.__metaclass__, type):
            return base.__metaclass__

    # If neither of the above methods returned a valid metaclass, use the default of type
    return type

