        raise TypeError("timestr must be a string")

    if default is not None and not isinstance(default, datetime.datetime):
        raise TypeError("default must be a datetime object")

    if tzinfos and not isinstance(tzinfos, dict):
        raise TypeError("tzinfos must be a dict")


    match = self._date_pattern.match(timestr)
    if not match:
        raise ParserError("String does not match format YYYY-MM-DD HH:MM:SS")


    year = int(match.group(1))
    if not 1 <= year <= 9999:
        raise ParserError("Year must be between 0001 and 9999")

    month = int(match.group(2))
    if not 1 <= month <= 12:
        raise ParserError("Month must be between 1 and 12")

    day = int(match.group(3))
    if not 1 <= day <= 31:
        raise ParserError("Day must be between 1 and 31")

    hour = int(match.group(4))
    if not 0 <= hour <= 23:
        raise ParserError("Hour must be between 0 and 23")

    minute = int(match.group(5))
    if not 0 <= minute <= 59:
        raise ParserError("Minute must be between 0 and 59")

    second = int(match.group(6))
    if not 0 <= second <= 59:
        raise ParserError("Second must be between 0 and 59")



    items = self._parse(timestr, default, ignoretz, tzinfos, **kwargs)
    if items is None:
        raise ParserError("Failed to parse date")

    if self._fuzzy and len(items) == 2 and items[1] > 0:
        raise ParserError("Fuzzy parsing not allowed")

    if len(items) == 1 and default is not None:
        return default.replace(year, month, day, hour, minute, second)
    else:
        return datetime.datetime(year, month, day, hour, minute, second)

