def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    curr_tag = ""
    new_text = ""
    for line in text.splitlines():
        stripped_line = line.strip()
        # Check if we are in a code block
        if (
            stripped_line.startswith("```")
            or stripped_line.startswith("``` ")
            or stripped_line.startswith("```\t")
        ):
            in_code_block = not in_code_block
        # Check if this is a tag
        match = re.match(r"(#[\w-_:]+\b)", stripped_line)
        if match:
            tag = match.group(1).strip()
            if tag not in tags:
                tags.add(tag)
                if replacer:
                    curr_tag = replacer(tag)
                else:
                    curr_tag = tag
            new_text += line + "\n"
        else:
            # If we are in a code block, don't replace anything
            if in_code_block:
                new_text += line + "\n"
            # If we are not in a code block, replace the tag words
            else:
                new_text += line.replace(curr_tag, "")
    return tags, new_text

