def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def linkify(text):
        """
        Take a text string and replace any URLs that can be extracted using the regular
        expression _PATH_RE with the corresponding file link.
        """
        def memoized_to_url(match):
            value = memoized_urls.get(match.group(0), _NO_URL)
            if value is _NO_URL:
                value = to_url(match)
                memoized_urls[match.group(0)] = value
            return value

        memoized_urls = {}

        def to_url(match):
            if match.group(1):
                return match.group(0)  # It's an http(s) url.
            path = match.group(0)

            if path.startswith('/'):
                path = os.path.relpath(path, buildroot)
            elif path.startswith('..'):
                # The path is not located inside the buildroot, so it's definitely not a BUILD file.
                return None
            else:
                # The path is located in the buildroot: see if it's a reference to a target in a BUILD file.
                parts = path.split(':')
                if len(parts) == 2:
                    putative_dir = parts[0]
                else:
                    putative_dir = path
                if os.path.isdir(os.path.join(buildroot, putative_dir)):
                    build_files = list(BuildFile.get_build_files_family(
                        FileSystemProjectTree(buildroot),
                        putative_dir))
                    if build_files:
                        path = build_files[0].relpath
                    else:
                        return None

            if os.path.exists(os.path.join(buildroot, path)):
                # The reporting server serves file content at /browse/<path_from_buildroot>.
                return '/browse/{}'.format(path)
            else:
                return None

        def maybe_add_link(url, text):
            return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

        return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

    def add_attrs(text):
        """
        Takes a string `text` and replaces occurrences of links (i.e. enclosed by \<a\> tags) with links that contain additional
        attributes, such as a custom name or target attribute.

        The attribute name is specified by `__attribute__` and the attribute value is specified by `__value__`.
        """
        def attr_regex(string, size, context, attribute, value):
            pattern = f'/'attr'[^{attribute} ]+__value__"'
            results = []
            i = 0
            while True:
                match = re.search(pattern, string[i:])
                if not match:
                    break
                results.append(match)
                i = match.end() + 1
            return results

        def attr_regex_callback(out, matches):
            for attr in results:
                start = attr.start()
                end = attr.end()
                url = attr.group(0)[1:]  # Remove the opening `<` character
                out.write(text[start:end] + href=url)
            return out.getvalue()

        memoized_urls = {}
        memoized_attrs = {}

        def to_attr(match):
            value = memoized_attrs.get(match.group(0), _NO_URL)
            if value is _NO_URL:
                value = to_attr_func(match)
            return value

        def to_attr_func(match):
            url = os.path.join(buildroot, match.group(0))
            if os.path.isdir(url):
                url = os.path.join(url, 'index.html')
            elif not os.path.isfile(url):
                url = ''
            return '<a target="_blank" href="{}">{}</a>'.format(url, match.group(0))

        return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

    def link_attrs(text):
        """
        Add a callback for adding attributes to links.

        The callback should take a single argument, the url, and
        should return additional text to be inserted in the link tag,
        i.e. ``"target="_blank"``.

        You can use this method as a decorator on the function you
        want to set as the callback.
        """
        def parse_attr(attr):
            if attr == 'target="_blank"':
                return '<a ' + attr + '>'
            else:
                return attr

        def link_attrs_callback(url, attr):
            if url:
                return '<a ' + parse_attr(attr) + '>' + url + '</a>'
            else:
                return url

        return _PATH_RE.sub(lambda m: link_attrs_callback(memoized_to_url(m), memoized_attrs(m)), text)

    # Set default values
    memoized_urls = {}
    memoized_attrs = {}

    # Process text links
    processed_text = process_text_links(text)

    # Add attribute text
    processed_text = add_attrs(processed_text)

    # Add link attributes
    processed_text = link_attrs(processed_text)

    return processed_text

