def _get_conditionally_required_args(self, command_name, options_spec, args):
    from collections import OrderedDict
    from taipan.strings import ensure_string
    ensure_string(command_name)

    option_dict = OrderedDict()
    for option in options_spec:
        ensure_dict(option)
        if 'required_when' in option and not isinstance(option['required_when'], list):
            raise TypeError('invalid type for required_when condition')
        option_dict[option['name']] = option

    required_args = []
    for arg in ensure_sequence(args):
        if arg in option_dict:
            required_when = option_dict[arg].get('required_when')
            if required_when and len(required_when) == 1:
                conditions = required_when[0]
                for condition, value in ensure_dict(conditions).items():
                    if arg in kwargs and ensure_string(kwargs[arg]) == value:
                        required_args.append(arg)
                        break
            elif required_when:
                for condition, value in ensure_dict(conditions).items():
                    if arg in kwargs and ensure_string(kwargs[arg]) == value:
                        break
                else:
                    required_args.append(arg)

    return required_args
